"OLAYLAR_ARKEOLOJI_PILOT:-9299-01-01:0":{"b": ["Երիքով (Թել ես-Սուլթան). սկսվում են ամենավաղ PPN շերտի (Stage IV/IVA) ռադիոածխածնային թվագրումները", "5ea619fa"], "d": ["Նատուֆյան հետքերն ավելի հին են (նույն էջում «11170–10980 BC» տրամաչափումը անորոշ է). նստակյաց PPN շերտի թվագրումները սկսվում են մ.թ.ա. 9300 թվականին։", "15c5503b"]},
"OLAYLAR_ARKEOLOJI_PILOT:-9528-01-01:0":{"b": ["Գյոբեքլի Թեփե. D շրջափակի (III շերտ) պատի ծեփի թվագրումը. մոնումենտալ կառուցման թվագրված ապացույցը", "4354b424"], "d": ["T-ձև կոթողներով շրջանաձև կառույցների (III շերտ, PPNA) թվագրվող ամենաուղղակի օրինակը պատի ծեփն է. լցանյութի նմուշները միայն ավերումից հետո ընկած ստորին սահմանն են։", "77cb01da"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0026-01-01:0":{"b": ["Հռոմ, Ալեքսանդրիա. Հռոմեական Հանրապետություն → անտեր միջակայք", "7df67fb7"], "d": ["Հռոմ, Ալեքսանդրիա կետերում տիրապետությունը Հռոմեական Հանրապետությունից անցնում է անտեր միջակայքի։ Աղբյուրի անցման տեղեկությունը. Թեոդոսիոսի մահը 395 թ. հունվարի 17-ին (Օլիբրիոսի և Պրոբոսի կոնսուլության տարին). Sokrates Scholastikos, Kil. Tar. 5.26 (NPNF, newadvent.org/fathers/26015.htm). Marcellinus Comes s.a. 395. Արկադիոսը և Հոնորիոսը կայսրությունը ժառանգում են բաժանված միայն նստավայրերով։", "5b0ba108"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0048-01-01:0":{"b": ["Մարսել, Մասալիա. Մասալիա (Մարսել) → Հռոմեական Հանրապետություն", "a9950655"], "d": ["Մարսել, Մասալիա կետերում տիրապետությունը Մասալիայից (Մարսել) անցնում է Հռոմեական Հանրապետությանը։ Աղբյուրի անցման տեղեկությունը. Caesar BC 2.22. քաղաքը պարտվելուց հետո «conservans» (խնայելով) և կայազոր թողնվեց. ազատ դաշնակցի կարգավիճակի վերջը, հռոմեական վերահսկողություն։", "51e72f2c"]},
"OLAYLAR_ARKEOLOJI_ZINCIR:-0085-01-01:0":{"b": ["Աթենք. սկսվում է Հռոմեական Հանրապետության շրջանը", "86f10b7f"], "d": ["Աթենք. սկսվում է Հռոմեական Հանրապետության շրջանը։ Այս թվականը առանձին իրադարձություն չէ, այն ցույց է տալիս այս շրջանի սկիզբը. մանրամասներն ու աղբյուրները ներկայացված են ստորև։", "deee676b"]},
